Cs(a){return"\u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0640 "+a},
gCT(){return"\u0628\u062f\u0621 \u0625\u062c\u0631\u0627\u0621"},
gzg(){return"\u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
gzd(){return"\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u062a\u0639\u0645\u0644: \u0633\u062a\u064f\u0633\u062c\u064e\u0651\u0644 \u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u0646\u0637\u0642\u0629."},
gtu(){return"\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0645\u064f\u0641\u0639\u0651\u0644\u0629 \u0644\u0643\u0646\u0647\u0627 \u0644\u0627 \u062a\u0639\u0645\u0644. \u0644\u0646 \u064a\u064f\u0633\u062c\u064e\u0651\u0644 \u0623\u064a \u062e\u0631\u0648\u062c \u062d\u062a\u0649 \u064a\u064f\u0635\u0644\u064e\u062d \u0630\u0644\u0643."},
gz1(){return"\u0627\u0644\u062e\u062f\u0645\u0629 \u062a\u0639\u0645\u0644"},
gyY(){return"\u0627\u0644\u0645\u0648\u0642\u0639 \xab\u062f\u0627\u0626\u0645\u064b\u0627\xbb"},
gyZ(){return"\u0627\u0644\u0628\u0637\u0627\u0631\u064a\u0629 \u063a\u064a\u0631 \u0645\u0642\u064a\u0651\u062f\u0629"},
gz2(){return"\u0645\u0646\u0627\u0637\u0642 \u0622\u0645\u0646\u0629 \u0645\u062d\u062f\u062f\u0629"},
gz0(){return"\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0628\u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0622\u0645\u0646\u0629"},
gyW(){return"\u0627\u0644\u0633\u0645\u0627\u062d \xab\u062f\u0627\u0626\u0645\u064b\u0627\xbb"},
gyU(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
gzj(){return"\u0627\u062e\u062a\u0628\u0631 \u0627\u0644\u0622\u0646"},
gzl(){return"\u062c\u0627\u0631\u064d \u0642\u064a\u0627\u0633 \u0645\u0648\u0642\u0639\u0643\u2026"},
gq2(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0648\u0642\u0639 \u2014 GPS \u0645\u0637\u0641\u0623 \u0623\u0648 \u062f\u0627\u062e\u0644 \u0645\u0628\u0646\u0649 \u0623\u0648 \u0627\u0644\u0625\u0630\u0646 \u0645\u0641\u0642\u0648\u062f."},
