yX(a,b){return"\u0622\u062e\u0631 \u0645\u0648\u0642\u0639: \u0645\u0646\u0630 "+a+" (\u062f\u0642\u0629 "+b+" \u0645)"},
gz4(){return"\u0644\u0645 \u064a\u064f\u0642\u064e\u0633 \u0623\u064a \u0645\u0648\u0642\u0639 \u0628\u0639\u062f."},
gtt(){return"\u062a\u062d\u0642\u0642 \u0645\u0646 \u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
HY(a){return"\u0623\u064f\u062d\u064a\u0644 \u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u0645\u0631\u0643\u0632 \u0627\u0644\u062a\u0646\u0638\u064a\u0645 (17) \u0628\u0648\u0627\u0633\u0637\u0629 "+a},
