HJ(a){return"\u0623\u0633\u0646\u062f \u0645\u0631\u0643\u0632 17 ("+a+") \u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u062c\u0647\u0629 \u062a\u062d\u0642\u064a\u0642"},
