gAS(){return"\u0647\u0644 \u0641\u0642\u062f\u062a \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629\u061f"},
gAP(){return"\u062a\u0623\u0643\u064a\u062f"},
gtN(){return"\u062a\u0645\u0651 \u0631\u0641\u0636 \u0627\u0644\u0631\u0645\u0632. \u064a\u062a\u063a\u064a\u0651\u0631 \u0643\u0644 30 \u062b\u0627\u0646\u064a\u0629 \u2014 \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0639\u0631\u0648\u0636 \u0627\u0644\u0622\u0646."},
