vt(a){return"\u0625\u0630\u0627 \u0642\u0628\u0644\u062a\u060c \u0641\u0633\u062a\u064f\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0644\u0633\u0628\u0628 \u0648\u0627\u062d\u062f \u0641\u0642\u0637: \u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0643 \u0625\u0646 \u0644\u0632\u0645 \u064a\u0648\u0645\u064b\u0627 \u0627\u0644\u0628\u062d\u062b \u0639\u0646 "+a+". \u0648\u0644\u0646 \u062a\u0643\u0648\u0646 \u0645\u0631\u0626\u064a\u0629 \u0625\u0644\u0627 \u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u062b\u0642\u0629 \u0627\u0644\u062e\u0627\u0635\u064a\u0646 \u0628\u0640"+a+" \u062f\u0627\u062e\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0644\u062a\u0646\u0633\u064a\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u0642\u0631\u0628\u064a\u0646 \u2014 \u0644\u0627 \u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0644\u0627 \u062a\u064f\u0646\u0634\u0631 \u0623\u0628\u062f\u064b\u0627. \u0644\u0627 \u0625\u0639\u0644\u0627\u0646\u0627\u062a\u060c \u0648\u0644\u0627 \u062a\u062a\u0628\u0639 \u0644\u0645\u0648\u0642\u0639\u0643."},
gFX(){return"\u064a\u0645\u0643\u0646\u0643 \u0637\u0644\u0628 \u062d\u0630\u0641\u0647\u0627 \u0641\u064a \u0623\u064a \u0648\u0642\u062a."},
