gKj(){return"\u062d\u0641\u0638 \u0628\u064a\u0627\u0646\u0627\u062a\u064a"},
gKk(){return"\u062a\u0645 \u062d\u0641\u0638 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a."},
gEZ(){return"\u0627\u062e\u062a\u0631 \u0645\u0646 \u062a\u0637\u0644\u0628 \u0645\u0646\u0647. \u0633\u064a\u0631\u0649 \u0647\u0624\u0644\u0627\u0621 \u0623\u064a\u0646 \u0623\u0646\u062a."},
